"""Sync mantle scenarios into Coval test sets."""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

from rasa.builder.copilot.mcp_server.tools.coval.client import CovalClient
from rasa.builder.copilot.mcp_server.tools.coval.filters import coval_filter_equals
from rasa.builder.copilot.mcp_server.tools.scenario import Scenario

_SCENARIO_INPUT_TYPE = "SCENARIO"


@dataclass(frozen=True)
class SyncManifestEntry:
    """Result of syncing one scenario to Coval."""

    scenario_slug: str
    test_case_id: Optional[str]
    action: str
    content_hash: str


def _scenario_payload(scenario: Scenario, test_set_id: str) -> Dict[str, Any]:
    return {
        "input_str": scenario.simulation_context.strip(),
        "test_set_id": test_set_id,
        "input_type": _SCENARIO_INPUT_TYPE,
        "expected_behaviors": list(scenario.goals.criteria),
        "metric_input": {"scenario_slug": scenario.slug},
        "description": scenario.name,
    }


def _content_hash(payload: Dict[str, Any]) -> str:
    canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _existing_payload_matches(
    existing: Dict[str, Any],
    payload: Dict[str, Any],
) -> bool:
    existing_behaviors = existing.get("expected_behaviors") or []
    payload_behaviors = payload.get("expected_behaviors") or []
    existing_metric = existing.get("metric_input") or {}
    payload_metric = payload.get("metric_input") or {}
    return (
        str(existing.get("input_str", "")).strip()
        == str(payload.get("input_str", "")).strip()
        and list(existing_behaviors) == list(payload_behaviors)
        and str(existing.get("input_type", _SCENARIO_INPUT_TYPE))
        == str(payload.get("input_type", _SCENARIO_INPUT_TYPE))
        and dict(existing_metric) == dict(payload_metric)
        and str(existing.get("description", "")).strip()
        == str(payload.get("description", "")).strip()
    )


async def list_test_cases_for_set(
    client: CovalClient,
    test_set_id: str,
) -> List[Dict[str, Any]]:
    test_cases: List[Dict[str, Any]] = []
    page_token: Optional[str] = None
    while True:
        params: Dict[str, str] = {
            "filter": coval_filter_equals("test_set_id", test_set_id),
            "page_size": "100",
        }
        if page_token:
            params["page_token"] = page_token
        data = await client._request("GET", "test-cases", params=params)
        page_items = data.get("test_cases", [])
        if isinstance(page_items, list):
            test_cases.extend(item for item in page_items if isinstance(item, dict))
        page_token = data.get("next_page_token")
        if not page_token:
            break
    return test_cases


def _find_test_case_by_slug(
    test_cases: List[Dict[str, Any]],
    scenario_slug: str,
) -> Optional[Dict[str, Any]]:
    for test_case in test_cases:
        metric_input = test_case.get("metric_input") or {}
        if metric_input.get("scenario_slug") == scenario_slug:
            return test_case
    return None


async def _upsert_scenario_with_existing_cases(
    client: CovalClient,
    scenario: Scenario,
    test_set_id: str,
    existing_cases: List[Dict[str, Any]],
) -> SyncManifestEntry:
    payload = _scenario_payload(scenario, test_set_id)
    content_hash = _content_hash(payload)
    existing = _find_test_case_by_slug(existing_cases, scenario.slug)

    if existing and _existing_payload_matches(existing, payload):
        test_case_id = existing.get("id")
        return SyncManifestEntry(
            scenario_slug=scenario.slug,
            test_case_id=str(test_case_id) if test_case_id else None,
            action="skipped",
            content_hash=content_hash,
        )

    if existing and existing.get("id"):
        test_case_id = str(existing["id"])
        update_body = {k: v for k, v in payload.items() if k != "test_set_id"}
        await client._request(
            "PATCH",
            f"test-cases/{test_case_id}",
            json_body=update_body,
        )
        return SyncManifestEntry(
            scenario_slug=scenario.slug,
            test_case_id=test_case_id,
            action="updated",
            content_hash=content_hash,
        )

    data = await client._request("POST", "test-cases", json_body=payload)
    created = data.get("test_case", data)
    test_case_id = created.get("id") if isinstance(created, dict) else None
    if isinstance(created, dict):
        existing_cases.append(created)
    return SyncManifestEntry(
        scenario_slug=scenario.slug,
        test_case_id=str(test_case_id) if test_case_id else None,
        action="created",
        content_hash=content_hash,
    )


async def sync_scenarios_to_test_set(
    client: CovalClient,
    scenarios: List[Scenario],
    test_set_id: str,
) -> List[SyncManifestEntry]:
    """Upsert multiple scenarios, listing existing test cases once."""
    existing_cases = await list_test_cases_for_set(client, test_set_id)
    return [
        await _upsert_scenario_with_existing_cases(
            client,
            scenario,
            test_set_id,
            existing_cases,
        )
        for scenario in scenarios
    ]


async def resolve_test_case_id_for_scenario(
    client: CovalClient,
    scenario: Scenario,
    test_set_id: str,
) -> str:
    """Return the Coval test case id for ``scenario.slug`` in ``test_set_id``.

    Raises:
        RuntimeError: when no matching test case exists in the test set.
    """
    existing_cases = await list_test_cases_for_set(client, test_set_id)
    existing = _find_test_case_by_slug(existing_cases, scenario.slug)
    if existing and existing.get("id"):
        return str(existing["id"])
    raise RuntimeError(
        f"No Coval test case with metric_input.scenario_slug={scenario.slug!r} "
        f"in test set {test_set_id}. Enable sync_scenarios or upsert the scenario "
        "to Coval first."
    )


async def sync_scenario_to_test_set(
    client: CovalClient,
    scenario: Scenario,
    test_set_id: str,
) -> SyncManifestEntry:
    """Upsert one scenario into a Coval test set, skipping when unchanged."""
    existing_cases = await list_test_cases_for_set(client, test_set_id)
    return await _upsert_scenario_with_existing_cases(
        client,
        scenario,
        test_set_id,
        existing_cases,
    )
